from typing import List

def rescale_to_unit(numbers: List[float]) -> List[float]:
    if not numbers:
        return numbers
    min_val = min(numbers)
    max_val = max(numbers)
    range_val = max_val - min_val
    if range_val == 0:
        return [0.0] * len(numbers)
    return [(n - min_val) / range_val for n in numbers]
```

